file.content:
{
	"$schema": "https://schemas.wp.org/trunk/theme.json",
	"version": 3,
	"settings": {
		"appearanceTools": true,
		"useRootPaddingAwareAlignments": true,
		"layout": {
			"contentSize": "800px",
			"wideSize": "1280px"
		},
		"color": {
			"palette": [
				{
					"slug": "background",
					"color": "#FDF6EC",
					"name": "Background (Cream)"
				},
				{
					"slug": "text",
					"color": "#1C1C1E",
					"name": "Text (Near-Black)"
				},
				{
					"slug": "muted",
					"color": "#5C5C60",
					"name": "Muted Text"
				},
				{
					"slug": "surface",
					"color": "#F7F1E6",
					"name": "Surface (Card)"
				},
				{
					"slug": "primary",
					"color": "#2D7A4F",
					"name": "Primary (Garden Green)"
				},
				{
					"slug": "primary-dark",
					"color": "#1B5E3A",
					"name": "Primary Dark (Forest)"
				},
				{
					"slug": "secondary",
					"color": "#F5A623",
					"name": "Secondary (Amber)"
				},
				{
					"slug": "tertiary",
					"color": "#7C4DFF",
					"name": "Tertiary (Violet)"
				},
				{
					"slug": "accent-orange",
					"color": "#FF6B35",
					"name": "Accent Orange"
				},
				{
					"slug": "accent-red",
					"color": "#E53935",
					"name": "Accent Red"
				},
				{
					"slug": "success",
					"color": "#34C759",
					"name": "Success Green"
				},
				{
					"slug": "white",
					"color": "#FFFFFF",
					"name": "White"
				},
				{
					"slug": "sage-mist",
					"color": "#E8F5E2",
					"name": "Sage Mist"
				}
			]
		},
		"typography": {
			"fontFamilies": [
				{
					"fontFamily": "'Nunito', sans-serif",
					"slug": "heading",
					"name": "Nunito (Headings)"
				},
				{
					"fontFamily": "'Nunito Sans', sans-serif",
					"slug": "body",
					"name": "Nunito Sans (Body)"
				},
				{
					"fontFamily": "'JetBrains Mono', monospace",
					"slug": "mono",
					"name": "JetBrains Mono"
				}
			],
			"fontSizes": [
				{
					"slug": "small",
					"size": "clamp(0.8125rem, 0.75rem + 0.25vw, 0.875rem)",
					"name": "Small",
					"fluid": false
				},
				{
					"slug": "medium",
					"size": "clamp(0.9375rem, 0.875rem + 0.3vw, 1.0625rem)",
					"name": "Medium",
					"fluid": false
				},
				{
					"slug": "large",
					"size": "clamp(1.125rem, 1rem + 0.5vw, 1.25rem)",
					"name": "Large",
					"fluid": false
				},
				{
					"slug": "x-large",
					"size": "clamp(1.375rem, 1.125rem + 1vw, 1.75rem)",
					"name": "X-Large",
					"fluid": false
				},
				{
					"slug": "xx-large",
					"size": "clamp(1.75rem, 1.25rem + 2vw, 2.75rem)",
					"name": "XX-Large",
					"fluid": false
				},
				{
					"slug": "display",
					"size": "clamp(2.5rem, 1.75rem + 3vw, 4.5rem)",
					"name": "Display",
					"fluid": false
				}
			]
		},
		"spacing": {
			"units": ["px", "em", "rem", "vh", "vw", "%"],
			"spacingSizes": [
				{
					"slug": "10",
					"size": "0.25rem",
					"name": "3XS"
				},
				{
					"slug": "20",
					"size": "0.5rem",
					"name": "2XS"
				},
				{
					"slug": "30",
					"size": "1rem",
					"name": "XS"
				},
				{
					"slug": "40",
					"size": "1.5rem",
					"name": "S"
				},
				{
					"slug": "50",
					"size": "2.5rem",
					"name": "M"
				},
				{
					"slug": "60",
					"size": "4rem",
					"name": "L"
				},
				{
					"slug": "70",
					"size": "5.5rem",
					"name": "XL"
				},
				{
					"slug": "80",
					"size": "7rem",
					"name": "2XL"
				}
			]
		}
	},
	"styles": {
		"color": {
			"background": "var:preset|color|background",
			"text": "var:preset|color|text"
		},
		"typography": {
			"fontFamily": "var:preset|font-family|body",
			"fontSize": "var:preset|font-size|medium",
			"lineHeight": "1.65",
			"fontWeight": "400"
		},
		"spacing": {
			"padding": {
				"top": "0",
				"bottom": "0",
				"left": "clamp(1.5rem, 5vw, 4rem)",
				"right": "clamp(1.5rem, 5vw, 4rem)"
			},
			"blockGap": "var:preset|spacing|40"
		},
		"elements": {
			"heading": {
				"typography": {
					"fontFamily": "var:preset|font-family|heading",
					"fontWeight": "800",
					"lineHeight": "1.15"
				},
				"color": {
					"text": "var:preset|color|text"
				}
			},
			"h1": {
				"typography": {
					"fontSize": "var:preset|font-size|display",
					"fontWeight": "900",
					"letterSpacing": "-0.03em"
				}
			},
			"h2": {
				"typography": {
					"fontSize": "var:preset|font-size|xx-large",
					"fontWeight": "800",
					"letterSpacing": "-0.02em"
				}
			},
			"h3": {
				"typography": {
					"fontSize": "var:preset|font-size|x-large",
					"fontWeight": "700"
				}
			},
			"h4": {
				"typography": {
					"fontSize": "var:preset|font-size|large",
					"fontWeight": "700"
				}
			},
			"h5": {
				"typography": {
					"fontSize": "var:preset|font-size|medium",
					"fontWeight": "700",
					"textTransform": "uppercase",
					"letterSpacing": "0.05em"
				}
			},
			"h6": {
				"typography": {
					"fontSize": "var:preset|font-size|small",
					"fontWeight": "700",
					"textTransform": "uppercase",
					"letterSpacing": "0.06em"
				}
			},
			"link": {
				"color": {
					"text": "var:preset|color|primary"
				},
				":hover": {
					"color": {
						"text": "var:preset|color|primary-dark"
					}
				}
			},
			"caption": {
				"typography": {
					"fontSize": "var:preset|font-size|small",
					"fontFamily": "var:preset|font-family|body"
				},
				"color": {
					"text": "var:preset|color|muted"
				}
			}
		},
		"blocks": {
			"core/navigation": {
				"typography": {
					"fontFamily": "var:preset|font-family|body",
					"fontSize": "var:preset|font-size|medium",
					"fontWeight": "600"
				},
				"color": {
					"text": "var:preset|color|text"
				},
				"spacing": {
					"blockGap": "var:preset|spacing|30"
				}
			},
			"core/site-title": {
				"typography": {
					"fontFamily": "var:preset|font-family|heading",
					"fontSize": "var:preset|font-size|x-large",
					"fontWeight": "900",
					"letterSpacing": "-0.5px"
				},
				"color": {
					"text": "var:preset|color|primary"
				},
				"elements": {
					"link": {
						"color": {
							"text": "var:preset|color|primary"
						},
						":hover": {
							"color": {
								"text": "var:preset|color|primary-dark"
							}
						}
					}
				}
			},
			"core/site-tagline": {
				"typography": {
					"fontSize": "var:preset|font-size|small",
					"fontWeight": "400"
				},
				"color": {
					"text": "var:preset|color|muted"
				}
			},
			"core/button": {
				"color": {
					"background": "var:preset|color|primary",
					"text": "var:preset|color|white"
				},
				":hover": {
					"color": {
						"background": "var:preset|color|primary-dark",
						"text": "var:preset|color|white"
					}
				},
				"typography": {
					"fontFamily": "var:preset|font-family|heading",
					"fontWeight": "800",
					"fontSize": "var:preset|font-size|medium"
				},
				"border": {
					"radius": "100px"
				},
				"spacing": {
					"padding": {
						"top": "var:preset|spacing|20",
						"bottom": "var:preset|spacing|20",
						"left": "var:preset|spacing|40",
						"right": "var:preset|spacing|40"
					}
				}
			},
			"core/buttons": {
				"spacing": {
					"blockGap": "var:preset|spacing|30"
				}
			},
			"core/post-template": {
				"spacing": {
					"blockGap": "var:preset|spacing|40"
				}
			},
			"core/query": {
				"spacing": {
					"blockGap": "var:preset|spacing|50"
				}
			},
			"core/columns": {
				"spacing": {
					"blockGap": "var:preset|spacing|40"
				}
			},
			"core/post-title": {
				"typography": {
					"fontFamily": "var:preset|font-family|heading",
					"fontSize": "var:preset|font-size|xx-large",
					"fontWeight": "800"
				},
				"color": {
					"text": "var:preset|color|text"
				},
				"elements": {
					"link": {
						"color": {
							"text": "var:preset|color|text"
						},
						":hover": {
							"color": {
								"text": "var:preset|color|primary"
							}
						}
					}
				}
			},
			"core/post-date": {
				"typography": {
					"fontSize": "var:preset|font-size|small",
					"fontWeight": "600"
				},
				"color": {
					"text": "var:preset|color|muted"
				}
			},
			"core/post-excerpt": {
				"typography": {
					"fontSize": "var:preset|font-size|medium",
					"lineHeight": "1.6"
				},
				"color": {
					"text": "var:preset|color|muted"
				}
			},
			"core/quote": {
				"typography": {
					"fontFamily": "var:preset|font-family|heading",
					"fontSize": "var:preset|font-size|large",
					"fontStyle": "normal",
					"fontWeight": "700"
				},
				"color": {
					"text": "var:preset|color|text"
				},
				"border": {
					"left": {
						"color": "var:preset|color|primary",
						"width": "4px",
						"style": "solid"
					}
				},
				"spacing": {
					"padding": {
						"left": "var:preset|spacing|40"
					}
				}
			},
			"core/code": {
				"typography": {
					"fontFamily": "var:preset|font-family|mono",
					"fontSize": "var:preset|font-size|small"
				},
				"color": {
					"background": "var:preset|color|surface",
					"text": "var:preset|color|text"
				},
				"border": {
					"radius": "12px"
				},
				"spacing": {
					"padding": {
						"top": "var:preset|spacing|30",
						"bottom": "var:preset|spacing|30",
						"left": "var:preset|spacing|40",
						"right": "var:preset|spacing|40"
					}
				}
			},
			"core/separator": {
				"color": {
					"text": "var:preset|color|surface"
				},
				"border": {
					"color": "var:preset|color|surface",
					"width": "1px"
				}
			},
			"core/image": {
				"border": {
					"radius": "20px"
				}
			},
			"core/pullquote": {
				"typography": {
					"fontFamily": "var:preset|font-family|heading",
					"fontSize": "var:preset|font-size|x-large",
					"fontWeight": "800",
					"lineHeight": "1.3"
				},
				"color": {
					"text": "var:preset|color|primary"
				},
				"border": {
					"top": {
						"color": "var:preset|color|primary",
						"width": "4px",
						"style": "solid"
					},
					"bottom": {
						"color": "var:preset|color|primary",
						"width": "4px",
						"style": "solid"
					}
				},
				"spacing": {
					"padding": {
						"top": "var:preset|spacing|40",
						"bottom": "var:preset|spacing|40"
					}
				}
			}
		}
	},
	"templateParts": [
		{
			"name": "header",
			"title": "Header",
			"area": "header"
		},
		{
			"name": "footer",
			"title": "Footer",
			"area": "footer"
		}
	],
	"customTemplates": [
		{
			"name": "page-no-title",
			"title": "Page (No Title)",
			"postTypes": ["page"]
		},
		{
			"name": "blank",
			"title": "Blank Canvas",
			"postTypes": ["page", "post"]
		}
	]
}

/*
Theme Name: EduHub
Theme URI: https://eduhub.uz
Author: EduHub Team
Description: A comprehensive educational platform theme for preschool through university students, featuring interactive learning, competitions, career guidance, and AI-powered exam preparation. Warm garden-inspired design with accessible typography.
Version: 1.0.0
License: GNU General Public License v2 or later
License URI: http://www.gnu.org/licenses/gpl-2.0.html
Text Domain: eduhub
Tags: education, block-patterns, full-site-editing, wide-blocks, block-styles, custom-colors, custom-fonts, translation-ready
Requires at least: 6.4
Tested up to: 6.7
Requires PHP: 7.4
*/

/* ==========================================================================
   Root & Global Resets
   ========================================================================== */

:root,
body,
.wp-site-blocks {
	overflow: visible;
}

/* Smooth scroll for anchor navigation */
html {
	scroll-behavior: smooth;
}

/* ==========================================================================
   Typography Polish
   ========================================================================== */

body {
	-webkit-font-smoothing: antialiased;
	-moz-osx-font-smoothing: grayscale;
	text-rendering: optimizeLegibility;
}

/* Heading refinements — rounded, warm, garden-inspired */
h1, h2, h3, h4, h5, h6,
.wp-block-heading {
	text-wrap: balance;
}

h1, .wp-block-heading:where([class*="has-display-font-size"]),
.wp-block-heading:where([class*="has-xx-large-font-size"]) {
	text-wrap: balance;
	word-break: break-word;
	overflow-wrap: break-word;
}

/* Paragraph polish */
p {
	text-wrap: pretty;
}

/* Monospace elements — score displays, code */
code,
kbd,
pre,
samp,
.wp-block-code,
.has-mono-font-family {
	font-variant-ligatures: none;
}

/* Caption treatment */
figcaption,
.wp-element-caption {
	font-style: italic;
	letter-spacing: 0.01em;
}

/* ==========================================================================
   Link Styles
   ========================================================================== */

a {
	transition: color 0.25s ease;
}

/* Underline links in prose content */
.entry-content a:not(.wp-block-button__link):not(.wp-block-navigation-item__content),
.wp-block-post-content a:not(.wp-block-button__link):not(.wp-block-navigation-item__content) {
	text-decoration: underline;
	text-decoration-color: var(--wp--preset--color--primary);
	text-underline-offset: 0.15em;
	text-decoration-thickness: 1.5px;
	transition: text-decoration-color 0.25s ease, color 0.25s ease;
}

.entry-content a:not(.wp-block-button__link):not(.wp-block-navigation-item__content):hover,
.wp-block-post-content a:not(.wp-block-button__link):not(.wp-block-navigation-item__content):hover {
	text-decoration-color: var(--wp--preset--color--primary-dark);
}

/* ==========================================================================
   Button Styles
   ========================================================================== */

.wp-block-button__link {
	transition: background-color 0.3s ease, color 0.3s ease, transform 0.3s ease, box-shadow 0.3s ease;
	letter-spacing: 0.01em;
}

.wp-block-button__link:hover {
	transform: translateY(-2px);
	box-shadow: 0 6px 20px rgba(45, 122, 79, 0.2);
}

.wp-block-button__link:active {
	transform: translateY(0);
	box-shadow: 0 2px 8px rgba(45, 122, 79, 0.15);
}

/* Outline button variant */
.wp-block-button.is-style-outline .wp-block-button__link {
	border-width: 2px;
	border-style: solid;
	background-color: transparent;
	transition: background-color 0.3s ease, color 0.3s ease, transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
}

.wp-block-button.is-style-outline .wp-block-button__link:hover {
	background-color: var(--wp--preset--color--primary);
	color: var(--wp--preset--color--white);
	border-color: var(--wp--preset--color--primary);
	transform: translateY(-2px);
	box-shadow: 0 6px 20px rgba(45, 122, 79, 0.2);
}

/* ==========================================================================
   Navigation Styles
   ========================================================================== */

.wp-block-navigation-item__content {
	position: relative;
	transition: color 0.25s ease;
}

.wp-block-navigation-item__content::after {
	content: '';
	position: absolute;
	bottom: -2px;
	left: 0;
	width: 0;
	height: 2px;
	background-color: var(--wp--preset--color--primary);
	border-radius: 2px;
	transition: width 0.3s ease;
}

.wp-block-navigation-item__content:hover::after,
.wp-block-navigation-item.current-menu-item .wp-block-navigation-item__content::after {
	width: 100%;
}

.wp-block-navigation-item__content:hover {
	color: var(--wp--preset--color--primary);
}

/* ==========================================================================
   Header — Fixed overlay with translucent-blur on scroll
   ========================================================================== */

.wp-site-blocks > header.wp-block-template-part {
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	z-index: 100;
}

/* Backdrop pseudo — keeps the header "clean" (no backdrop-filter) so the
   mobile nav overlay's position: fixed inset: 0 targets the viewport. */
.wp-site-blocks > header.wp-block-template-part::before {
	content: "";
	position: absolute;
	inset: 0;
	z-index: -1;
	pointer-events: none;
	transition: background 0.4s ease, backdrop-filter 0.4s ease, -webkit-backdrop-filter 0.4s ease;
}

body.is-scrolled .wp-site-blocks > header.wp-block-template-part::before {
	background: color-mix(in srgb, var(--wp--preset--color--background) 80%, transparent);
	backdrop-filter: blur(16px);
	-webkit-backdrop-filter: blur(16px);
	box-shadow: 0 1px 0 rgba(28, 28, 30, 0.06);
}

/* Header inner group transition */
@media (prefers-reduced-motion: no-preference) {
	.wp-site-blocks > header.wp-block-template-part > .wp-block-group {
		transition: padding 0.3s ease;
	}
}

/* ==========================================================================
   Mobile Navigation Overlay
   ========================================================================== */

.wp-block-navigation__responsive-container.is-menu-open {
	padding: var(--wp--preset--spacing--60) var(--wp--preset--spacing--40);
}

.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation__container {
	gap: var(--wp--preset--spacing--40);
	align-items: flex-start;
}

.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation-item__content {
	font-size: var(--wp--preset--font-size--large);
}

/* ==========================================================================
   Image Treatments
   ========================================================================== */

.wp-block-image img,
.wp-block-cover__image-background {
	transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

/* Gentle zoom on hover for linked images */
a:hover .wp-block-image img,
.wp-block-image a:hover img {
	transform: scale(1.03);
}

/* Image shape — soft corners for warmth */
.wp-block-image {
	overflow: hidden;
}

.wp-block-image.is-style-rounded img {
	border-radius: 50%;
}

/* Gallery spacing refinement */
.wp-block-gallery {
	--wp--style--gallery-gap-default: var(--wp--preset--spacing--20);
}

.wp-block-gallery .wp-block-image {
	border-radius: 12px;
	overflow: hidden;
}

/* ==========================================================================
   Card / Surface Styles
   ========================================================================== */

/* Lift effect for card-like groups */
.wp-block-group:where([class*="has-surface-background-color"]) {
	border-radius: 20px;
	transition: transform 0.3s ease, box-shadow 0.3s ease;
	box-shadow: 0 4px 16px rgba(28, 28, 30, 0.04);
}

.wp-block-group:where([class*="has-surface-background-color"]):hover {
	box-shadow: 0 12px 32px rgba(45, 122, 79, 0.08);
}

/* ==========================================================================
   Cover Block Polish
   ========================================================================== */

.wp-block-cover {
	border-radius: 0;
}

.wp-block-cover .wp-block-cover__inner-container {
	z-index: 1;
}

/* ==========================================================================
   Quote & Pullquote
   ========================================================================== */

.wp-block-quote cite,
.wp-block-pullquote cite {
	font-family: var(--wp--preset--font-family--body);
	font-weight: 600;
	font-size: var(--wp--preset--font-size--small);
	color: var(--wp--preset--color--muted);
	font-style: normal;
	display: block;
	margin-top: var(--wp--preset--spacing--20);
}

.wp-block-quote p,
.wp-block-pullquote p {
	margin-bottom: 0;
}

/* ==========================================================================
   Separator Polish
   ========================================================================== */

.wp-block-separator:not(.is-style-wide):not(.is-style-dots) {
	max-width: 120px;
}

.wp-block-separator.is-style-dots::before {
	color: var(--wp--preset--color--primary);
}

/* ==========================================================================
   Code Block
   ========================================================================== */

.wp-block-code code {
	display: block;
	white-space: pre-wrap;
	word-break: break-word;
	line-height: 1.7;
	tab-size: 4;
}

/* ==========================================================================
   Post Template & Query Loop Cards
   ========================================================================== */

.wp-block-post-template .wp-block-post {
	transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.wp-block-post-template .wp-block-post:hover {
	transform: translateY(-4px);
}

/* Post featured image in cards */
.wp-block-post-featured-image img {
	border-radius: 12px;
	transition: transform 0.4s ease;
}

.wp-block-post:hover .wp-block-post-featured-image img {
	transform: scale(1.03);
}

.wp-block-post-featured-image {
	overflow: hidden;
	border-radius: 12px;
}

/* Post title link hover */
.wp-block-post-title a {
	text-decoration: none;
	transition: color 0.25s ease;
}

.wp-block-post-title a:hover {
	color: var(--wp--preset--color--primary);
}

/* ==========================================================================
   Site Title
   ========================================================================== */

.wp-block-site-title a {
	text-decoration: none;
}

/* ==========================================================================
   Columns — responsive stacking
   ========================================================================== */

@media (max-width: 781px) {
	.wp-block-columns {
		flex-wrap: wrap;
	}

	.wp-block-columns > .wp-block-column {
		flex-basis: 100% !important;
	}
}

/* ==========================================================================
   Accent Color Utility — Age Group CTAs (referenced in hero)
   ========================================================================== */

/* These classes can be applied to groups/buttons for age-group color coding */
.has-secondary-border-color {
	border-color: var(--wp--preset--color--secondary);
}

.has-tertiary-border-color {
	border-color: var(--wp--preset--color--tertiary);
}

.has-accent-orange-border-color {
	border-color: var(--wp--preset--color--accent-orange);
}

.has-accent-red-border-color {
	border-color: var(--wp--preset--color--accent-red);
}

/* ==========================================================================
   Live Badge
   ========================================================================== */

@keyframes pulse-glow {
	0% { box-shadow: 0 0 0 0 rgba(229, 57, 53, 0.4); }
	70% { box-shadow: 0 0 0 8px rgba(229, 57, 53, 0); }
	100% { box-shadow: 0 0 0 0 rgba(229, 57, 53, 0); }
}

.live-badge {
	display: inline-flex;
	align-items: center;
	gap: 4px;
	background-color: var(--wp--preset--color--accent-red);
	color: var(--wp--preset--color--white);
	font-family: var(--wp--preset--font-family--heading);
	font-size: var(--wp--preset--font-size--small);
	font-weight: 800;
	text-transform: uppercase;
	padding: 0.25rem 0.625rem;
	border-radius: 6px;
	animation: pulse-glow 2s infinite;
}

/* ==========================================================================
   Glassmorphism utility for floating cards
   ========================================================================== */

.glass-card {
	background: rgba(255, 255, 255, 0.85);
	backdrop-filter: blur(12px);
	-webkit-backdrop-filter: blur(12px);
	border: 1px solid rgba(255, 255, 255, 0.4);
	border-radius: 20px;
	box-shadow: 0 20px 40px rgba(0, 0, 0, 0.06);
}

/* ==========================================================================
   Subtle dot pattern overlay (hero backgrounds)
   ========================================================================== */

.dot-pattern::before {
	content: '';
	position: absolute;
	inset: 0;
	background-image: radial-gradient(var(--wp--preset--color--primary) 1px, transparent 1px);
	background-size: 40px 40px;
	opacity: 0.03;
	pointer-events: none;
	z-index: 0;
}

/* ==========================================================================
   Decorative orbs (soft blurred circles in hero)
   ========================================================================== */

.orb {
	position: absolute;
	border-radius: 50%;
	filter: blur(60px);
	opacity: 0.5;
	pointer-events: none;
	z-index: 0;
}

.orb-amber {
	background-color: var(--wp--preset--color--secondary);
	opacity: 0.25;
}

.orb-green {
	background-color: var(--wp--preset--color--primary);
	opacity: 0.15;
}

/* ==========================================================================
   Focus Styles — Accessible & On-Brand
   ========================================================================== */

:focus-visible {
	outline: 2px solid var(--wp--preset--color--primary);
	outline-offset: 2px;
	border-radius: 4px;
}

.wp-block-button__link:focus-visible {
	outline-offset: 4px;
	box-shadow: 0 0 0 2px var(--wp--preset--color--background), 0 0 0 4px var(--wp--preset--color--primary);
}

/* ==========================================================================
   Selection Color
   ========================================================================== */

::selection {
	background-color: var(--wp--preset--color--sage-mist);
	color: var(--wp--preset--color--text);
}

/* ==========================================================================
   Scroll Progress Bar
   ========================================================================== */

@media (prefers-reduced-motion: no-preference) {
	@supports (animation-timeline: scroll()) {
		.scroll-progress {
			position: fixed;
			top: 0;
			left: 0;
			right: 0;
			height: 3px;
			background: var(--wp--preset--color--primary);
			transform-origin: left center;
			transform: scaleX(0);
			z-index: 1000;
			animation: scroll-progress-grow linear;
			animation-timeline: scroll(root);
		}

		@keyframes scroll-progress-grow {
			from { transform: scaleX(0); }
			to { transform: scaleX(1); }
		}
	}
}

/* ==========================================================================
   Tables
   ========================================================================== */

.wp-block-table table {
	border-collapse: collapse;
	width: 100%;
}

.wp-block-table td,
.wp-block-table th {
	border-color: var(--wp--preset--color--surface);
	padding: var(--wp--preset--spacing--20) var(--wp--preset--spacing--30);
}

.wp-block-table thead {
	border-bottom: 2px solid var(--wp--preset--color--primary);
}

.wp-block-table thead th {
	font-family: var(--wp--preset--font-family--heading);
	font-weight: 700;
	text-align: start;
}

.wp-block-table.is-style-stripes tbody tr:nth-child(odd) {
	background-color: var(--wp--preset--color--surface);
}

/* ==========================================================================
   Details / Accordion Block (FAQ)
   ========================================================================== */

.wp-block-details {
	border-bottom: 1px solid var(--wp--preset--color--surface);
	padding-block: var(--wp--preset--spacing--30);
}

.wp-block-details summary {
	font-family: var(--wp--preset--font-family--heading);
	font-weight: 700;
	font-size: var(--wp--preset--font-size--large);
	cursor: pointer;
	list-style: none;
	display: flex;
	justify-content: space-between;
	align-items: center;
	gap: var(--wp--preset--spacing--20);
	transition: color 0.25s ease;
}

.wp-block-details summary:hover {
	color: var(--wp--preset--color--primary);
}

.wp-block-details summary::after {
	content: '+';
	font-size: 1.5em;
	line-height: 1;
	color: var(--wp--preset--color--primary);
	flex-shrink: 0;
	transition: transform 0.3s ease;
}

.wp-block-details[open] summary::after {
	transform: rotate(45deg);
}

.wp-block-details summary::-webkit-details-marker {
	display: none;
}

/* ==========================================================================
   Pricing Card Hover
   ========================================================================== */

.pricing-card {
	transition: transform 0.3s ease, box-shadow 0.3s ease;
	border-radius: 20px;
}

.pricing-card:hover {
	transform: translateY(-6px);
	box-shadow: 0 20px 48px rgba(45, 122, 79, 0.12);
}

/* Featured/highlighted pricing tier */
.pricing-featured {
	position: relative;
	border: 2px solid var(--wp--preset--color--primary);
}

.pricing-featured::before {
	content: '';
	position: absolute;
	inset: -2px;
	border-radius: 22px;
	background: linear-gradient(135deg, var(--wp--preset--color--primary), var(--wp--preset--color--tertiary));
	z-index: -1;
	opacity: 0.1;
}

/* ==========================================================================
   Tag / Badge Utility
   ========================================================================== */

.badge {
	display: inline-block;
	font-family: var(--wp--preset--font-family--heading);
	font-weight: 700;
	font-size: var(--wp--preset--font-size--small);
	letter-spacing: 0.03em;
	padding: 0.2em 0.75em;
	border-radius: 100px;
	line-height: 1.5;
}

/* ==========================================================================
   Smooth page-level transitions
   ========================================================================== */

@media (prefers-reduced-motion: no-preference) {
	.wp-block-cover,
	.wp-block-group,
	.wp-block-columns {
		transition: opacity 0.1s ease;
	}
}

/* ==========================================================================
   Footer Credit Link Styles
   ========================================================================== */

footer a {
	text-decoration: underline;
	text-decoration-color: currentColor;
	text-underline-offset: 0.15em;
	text-decoration-thickness: 1px;
	transition: opacity 0.25s ease;
}

footer a:hover {
	opacity: 0.75;
}

/* ==========================================================================
   Loop Layout Utilities
   ========================================================================== */
/* These classes are wired to the wp:query blocks emitted by content/pages and
   templates. Do not rename. Tuned to theme.json tokens. */

/* Horizontal scrollable rail */
.wp-block-query.is-style-loop-rail .wp-block-post-template {
	overflow-x: auto;
	scroll-snap-type: x mandatory;
	scrollbar-width: thin;
	padding-bottom: var(--wp--preset--spacing--20);
}

.wp-block-query.is-style-loop-rail .wp-block-post-template > * {
	flex: 0 0 320px;
	scroll-snap-align: start;
}

/* Compact list with hairline row dividers */
.wp-block-query.is-style-loop-list .wp-block-post-template > * {
	border-bottom: 1px solid var(--wp--preset--color--surface);
	padding-block: var(--wp--preset--spacing--30);
}

.wp-block-query.is-style-loop-list .wp-block-post-template > *:last-child {
	border-bottom: 0;
}

/* Zigzag — flip the columns inside every even entry */
.wp-block-query.is-style-loop-zigzag .wp-block-post-template > *:nth-child(even) .wp-block-columns {
	flex-direction: row-reverse;
}

/* Timeline — vertical line with node markers per entry */
.wp-block-query.is-style-loop-timeline .wp-block-post-template {
	position: relative;
	padding-inline-start: 2.5rem;
}

.wp-block-query.is-style-loop-timeline .wp-block-post-template::before {
	content: '';
	position: absolute;
	inset-block: 0;
	inset-inline-start: 0.5rem;
	width: 2px;
	background: var(--wp--preset--color--primary);
	opacity: 0.15;
}

.wp-block-query.is-style-loop-timeline .wp-block-post-template > * {
	position: relative;
}

.wp-block-query.is-style-loop-timeline .wp-block-post-template > *::before {
	content: '';
	position: absolute;
	inset-inline-start: -2.25rem;
	inset-block-start: 0.6rem;
	width: 1rem;
	height: 1rem;
	border: 2px solid var(--wp--preset--color--primary);
	border-radius: 50%;
	background: var(--wp--preset--color--background);
}

/* Magazine — first child spans 2 columns of the grid */
.wp-block-query.is-style-loop-magazine .wp-block-post-template > *:first-child {
	grid-column: span 2;
}

@media (max-width: 600px) {
	.wp-block-query.is-style-loop-magazine .wp-block-post-template > *:first-child {
		grid-column: auto;
	}
}

{
    "name": "telex-eduhub",
    "version": "0.1.0",
    "description": "EduHub Learning Platform \u2014 WordPress block theme",
    "private": true,
    "scripts": {
        "build": "wp-scripts build --webpack-src-dir=blocks/contact-form/src --output-path=blocks/contact-form/build"
    },
    "devDependencies": {
        "@wordpress/scripts": "^30.15.0"
    }
}

{
	"$schema": "https://schemas.wp.org/trunk/block.json",
	"apiVersion": 3,
	"name": "eduhub/contact-form",
	"title": "Contact Form",
	"category": "widgets",
	"description": "Front-end contact and support inquiry form collecting visitor name, email, subject, and message. Persists each submission to the eduhub_inquiry CPT via the REST API.",
	"supports": {
		"html": false,
		"color": {
			"background": true,
			"text": true
		},
		"spacing": {
			"padding": true,
			"margin": true
		},
		"typography": {
			"fontSize": true
		}
	},
	"attributes": {
		"buttonLabel": {
			"type": "string",
			"default": "Yuborish"
		},
		"successMessage": {
			"type": "string",
			"default": "Rahmat! Xabaringiz muvaffaqiyatli yuborildi. Tez orada siz bilan bog'lanamiz."
		},
		"namePlaceholder": {
			"type": "string",
			"default": "Ismingiz"
		},
		"emailPlaceholder": {
			"type": "string",
			"default": "Elektron pochtangiz"
		},
		"subjectPlaceholder": {
			"type": "string",
			"default": "Mavzu"
		},
		"messagePlaceholder": {
			"type": "string",
			"default": "Xabaringizni yozing..."
		}
	},
	"editorScript": "file:./index.js",
	"editorStyle": "file:./index.css",
	"style": "file:./style-index.css",
	"render": "file:./render.php",
	"viewScript": "file:./view.js"
}

export default function save() {
	return null;
}

import { registerBlockType } from '@wordpress/blocks';
import metadata from './block.json';
import Edit from './edit';
import save from './save';
import './style.scss';
import './editor.scss';

registerBlockType( metadata.name, {
	edit: Edit,
	save,
} );

.wp-block-eduhub-contact-form {
	max-width: 640px;
	margin-left: auto;
	margin-right: auto;
	font-family: var(--wp--preset--font-family--body);
}

.eduhub-contact-form__field {
	margin-bottom: var(--wp--preset--spacing--30);
}

.eduhub-contact-form__label {
	display: block;
	font-family: var(--wp--preset--font-family--heading);
	font-weight: 700;
	font-size: var(--wp--preset--font-size--medium);
	color: var(--wp--preset--color--text);
	margin-bottom: var(--wp--preset--spacing--10);
}

.eduhub-contact-form__input,
.eduhub-contact-form__textarea {
	display: block;
	width: 100%;
	font-family: var(--wp--preset--font-family--body);
	font-size: var(--wp--preset--font-size--medium);
	color: var(--wp--preset--color--text);
	background-color: var(--wp--preset--color--surface);
	border: 2px solid transparent;
	border-radius: 12px;
	padding: var(--wp--preset--spacing--20) var(--wp--preset--spacing--30);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
	outline: none;
	line-height: 1.5;
}

.eduhub-contact-form__input::placeholder,
.eduhub-contact-form__textarea::placeholder {
	color: var(--wp--preset--color--muted);
}

.eduhub-contact-form__input:focus,
.eduhub-contact-form__textarea:focus {
	border-color: var(--wp--preset--color--primary);
	box-shadow: 0 0 0 3px rgba(45, 122, 79, 0.12);
}

.eduhub-contact-form__input:invalid:not(:placeholder-shown),
.eduhub-contact-form__textarea:invalid:not(:placeholder-shown) {
	border-color: var(--wp--preset--color--accent-red);
	box-shadow: 0 0 0 3px rgba(229, 57, 53, 0.1);
}

.eduhub-contact-form__textarea {
	resize: vertical;
	min-height: 120px;
}

.eduhub-contact-form__actions {
	margin-top: var(--wp--preset--spacing--40);
}

.eduhub-contact-form__submit {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	gap: var(--wp--preset--spacing--20);
	font-family: var(--wp--preset--font-family--heading);
	font-weight: 800;
	font-size: var(--wp--preset--font-size--medium);
	color: var(--wp--preset--color--white);
	background-color: var(--wp--preset--color--primary);
	border: none;
	border-radius: 100px;
	padding: var(--wp--preset--spacing--20) var(--wp--preset--spacing--50);
	cursor: pointer;
	transition: background-color 0.3s ease, transform 0.3s ease, box-shadow 0.3s ease;
	letter-spacing: 0.01em;
	min-width: 160px;
}

.eduhub-contact-form__submit:hover {
	background-color: var(--wp--preset--color--primary-dark);
	transform: translateY(-2px);
	box-shadow: 0 6px 20px rgba(45, 122, 79, 0.2);
}

.eduhub-contact-form__submit:active {
	transform: translateY(0);
	box-shadow: 0 2px 8px rgba(45, 122, 79, 0.15);
}

.eduhub-contact-form__submit:disabled {
	opacity: 0.7;
	cursor: not-allowed;
	transform: none;
	box-shadow: none;
}

.eduhub-contact-form__submit:focus-visible {
	outline: 2px solid var(--wp--preset--color--primary);
	outline-offset: 4px;
	box-shadow: 0 0 0 2px var(--wp--preset--color--background), 0 0 0 4px var(--wp--preset--color--primary);
}

.eduhub-contact-form__spinner {
	display: inline-block;
	width: 18px;
	height: 18px;
	border: 2.5px solid rgba(255, 255, 255, 0.3);
	border-top-color: var(--wp--preset--color--white);
	border-radius: 50%;
	animation: eduhub-spin 0.6s linear infinite;
}

@keyframes eduhub-spin {
	to {
		transform: rotate(360deg);
	}
}

.eduhub-contact-form__status {
	margin-top: var(--wp--preset--spacing--30);
	font-size: var(--wp--preset--font-size--medium);
	font-weight: 600;
	line-height: 1.5;
	min-height: 1.5em;
}

.eduhub-contact-form__status--success {
	color: var(--wp--preset--color--primary);
}

.eduhub-contact-form__status--error {
	color: var(--wp--preset--color--accent-red);
}

.eduhub-contact-form__status--sending {
	color: var(--wp--preset--color--muted);
}

.eduhub-contact-form--editor {
	.eduhub-contact-form__input,
	.eduhub-contact-form__textarea {
		opacity: 0.85;
	}

	.eduhub-contact-form__submit {
		pointer-events: none;
	}

	.eduhub-contact-form__status--preview {
		color: var(--wp--preset--color--muted);
		font-size: var(--wp--preset--font-size--small);
		font-style: italic;
	}
}

document.addEventListener( 'DOMContentLoaded', () => {
	const forms = document.querySelectorAll( '.wp-block-eduhub-contact-form' );

	forms.forEach( ( form ) => {
		const submitBtn = form.querySelector( '.eduhub-contact-form__submit' );
		const submitText = form.querySelector( '.eduhub-contact-form__submit-text' );
		const statusEl = form.querySelector( '.eduhub-contact-form__status' );

		if ( ! submitBtn || ! statusEl ) {
			return;
		}

		const originalLabel = submitText ? submitText.textContent : 'Yuborish';

		form.addEventListener( 'submit', async ( event ) => {
			event.preventDefault();

			statusEl.textContent = '';
			statusEl.className = 'eduhub-contact-form__status';

			if ( ! form.checkValidity() ) {
				const firstInvalid = form.querySelector( ':invalid' );
				if ( firstInvalid ) {
					firstInvalid.focus();
				}
				statusEl.textContent = 'Iltimos, barcha majburiy maydonlarni to\'ldiring.';
				statusEl.classList.add( 'eduhub-contact-form__status--error' );
				return;
			}

			const emailInput = form.querySelector( 'input[name="email"]' );
			if ( emailInput ) {
				const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
				if ( ! emailPattern.test( emailInput.value.trim() ) ) {
					emailInput.focus();
					statusEl.textContent = 'Iltimos, to\'g\'ri elektron pochta manzilini kiriting.';
					statusEl.classList.add( 'eduhub-contact-form__status--error' );
					return;
				}
			}

			submitBtn.disabled = true;
			statusEl.textContent = 'Yuborilmoqda...';
			statusEl.classList.add( 'eduhub-contact-form__status--sending' );

			if ( submitText ) {
				submitText.innerHTML =
					'<span class="eduhub-contact-form__spinner"></span> Yuborilmoqda...';
			}

			const formData = new FormData( form );
			const body = {};
			formData.forEach( ( value, key ) => {
				body[ key ] = value.trim();
			} );

			try {
				const response = await fetch( form.dataset.endpoint, {
					method: 'POST',
					headers: {
						'Content-Type': 'application/json',
						'X-WP-Nonce': form.dataset.nonce,
					},
					body: JSON.stringify( body ),
				} );

				const data = await response.json();

				if ( ! response.ok ) {
					throw new Error(
						data?.message || 'Xabar yuborishda xatolik yuz berdi.'
					);
				}

				form.reset();
				statusEl.className = 'eduhub-contact-form__status';
				statusEl.classList.add(
					'eduhub-contact-form__status--success'
				);
				statusEl.textContent =
					form.dataset.success ||
					'Rahmat! Xabaringiz muvaffaqiyatli yuborildi.';
			} catch ( error ) {
				statusEl.className = 'eduhub-contact-form__status';
				statusEl.classList.add( 'eduhub-contact-form__status--error' );
				statusEl.textContent = error.message;
			} finally {
				submitBtn.disabled = false;
				if ( submitText ) {
					submitText.textContent = originalLabel;
				}
			}
		} );
	} );
} );

/**
 * Theme Assets Editor Rewrite
 *
 * This script rewrites URLs in block attributes that start with 'theme:./'
 * to point to the correct theme assets.
 * It allows blocks in templates to reference theme assets using relative paths in the editor.
**/
(function (wp) {
	const base = window.THEME_ASSETS_BASE_URL || '';
	const prefix = 'theme:./';

	if (!wp?.hooks || !wp?.compose) return;

	const rewrite = (url) => {
		if (typeof url === 'string' && url.startsWith(prefix)) {
			const path = url.slice(prefix.length);
			return base + '/' + path;
		}
		return null;
	};

	// Recursively walk any value and rewrite all theme:./ URLs found in it.
	// Returns a new structure if anything changed, or null if nothing changed.
	const deepRewrite = (value) => {
		if (typeof value === 'string') {
			return rewrite(value);
		}
		if (Array.isArray(value)) {
			let changed = false;
			const result = value.map((item) => {
				const rewritten = deepRewrite(item);
				if (rewritten !== null) {
					changed = true;
					return rewritten;
				}
				return item;
			});
			return changed ? result : null;
		}
		if (value && typeof value === 'object') {
			let changed = false;
			const result = {};
			for (const key of Object.keys(value)) {
				const rewritten = deepRewrite(value[key]);
				if (rewritten !== null) {
					changed = true;
					result[key] = rewritten;
				} else {
					result[key] = value[key];
				}
			}
			return changed ? result : null;
		}
		return null;
	};

	wp.hooks.addFilter(
		'editor.BlockEdit',
		'theme-assets/rewrite-image-urls',
		wp.compose.createHigherOrderComponent((BlockEdit) => (props) => {
			const { attributes } = props;

			// Deep-rewrite all attributes to resolve any theme:./ URLs
			const rewrittenAttributes = deepRewrite(attributes);

			// Pass rewritten URLs to BlockEdit for display only, without persisting changes
			if (rewrittenAttributes) {
				const modifiedProps = {
					...props,
					attributes: rewrittenAttributes,
				};
				return wp.element.createElement(BlockEdit, modifiedProps);
			}

			return wp.element.createElement(BlockEdit, props);
		}, 'withThemeAssetsRewrite')
	);

})(window.wp);

/**
 * On landing-page themes whose nav is in-page anchor links (href="#history",
 * etc.), toggles `.is-active` on the nav link matching whichever anchored
 * section is currently in the viewport's middle band. style.css drives the
 * visual treatment (underline, color shift, etc.) off that class.
 *
 * Gated on prefers-reduced-motion: users who opted out of motion don't
 * get the active-anchor animation. Static layout still works — the nav
 * links remain functional, just without the rolling highlight.
 *
 * Deterministically injected into every theme by AddArbitraryFilesToArtefactTask;
 * functions.php enqueues it only on landing-page themes that want the
 * active-anchor variant.
 */
(function () {
    'use strict';

    function init() {
        if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
            return;
        }
        var sections = document.querySelectorAll('main [id]');
        var navLinks = document.querySelectorAll('.wp-block-navigation a[href^="#"]');
        if (!sections.length || !navLinks.length || typeof IntersectionObserver === 'undefined') {
            return;
        }
        var linksBySlug = {};
        navLinks.forEach(function (link) {
            var href = link.getAttribute('href') || '';
            var hash = href.charAt(0) === '#' ? href.slice(1) : '';
            if (hash) {
                linksBySlug[hash] = link;
            }
        });
        var io = new IntersectionObserver(function (entries) {
            entries.forEach(function (entry) {
                var link = linksBySlug[entry.target.id];
                if (!link) {
                    return;
                }
                if (entry.isIntersecting) {
                    Object.keys(linksBySlug).forEach(function (slug) {
                        linksBySlug[slug].classList.remove('is-active');
                    });
                    link.classList.add('is-active');
                }
            });
        }, { rootMargin: '-40% 0px -40% 0px' });
        sections.forEach(function (s) { io.observe(s); });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();

/**
 * Adds `.is-visible` to every `.reveal-on-scroll` element as it enters the
 * viewport. style.css drives the fade-in + slide-up off that class. Once
 * an element has been revealed it is unobserved — no re-trigger on scroll
 * back, no flicker.
 *
 * Gated on prefers-reduced-motion: users who opted out of motion never see
 * any reveal animation; the elements render in their final state from page
 * load. style.css handles the static fallback via the `@media
 * (prefers-reduced-motion: no-preference)` wrapper around the .reveal-on-scroll
 * rules — when motion is reduced, those rules don't apply and elements stay
 * fully visible at opacity 1 / translateY(0).
 *
 * Deterministically injected into every theme by AddArbitraryFilesToArtefactTask;
 * functions.php enqueues it only when the home or interior page actually
 * uses .reveal-on-scroll in its block markup.
 */
(function () {
    'use strict';

    function init() {
        if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
            return;
        }
        var targets = document.querySelectorAll('.reveal-on-scroll');
        if (!targets.length || typeof IntersectionObserver === 'undefined') {
            // No targets, or ancient browser — bail. The static fallback
            // in style.css keeps elements visible regardless.
            return;
        }
        var io = new IntersectionObserver(function (entries) {
            entries.forEach(function (entry) {
                if (entry.isIntersecting) {
                    entry.target.classList.add('is-visible');
                    io.unobserve(entry.target);
                }
            });
        }, { threshold: 0.12, rootMargin: '0px 0px -10% 0px' });
        targets.forEach(function (el) { io.observe(el); });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();

/**
 * Animates `.counter[data-counter-target]` elements from 0 up to their target
 * value when they enter the viewport. Optional `data-counter-suffix` is
 * appended (e.g. "+", "%", "k"). Numbers render with thousand-separators
 * via toLocaleString — "600000" displays as "600,000".
 *
 * Gated on prefers-reduced-motion: users who opted out of motion see the
 * final value rendered immediately, no count-up.
 *
 * Deterministically injected into every theme by AddArbitraryFilesToArtefactTask;
 * functions.php enqueues it only when the home page actually uses .counter
 * blocks.
 */
(function () {
    'use strict';

    function renderFinal(el) {
        var target = parseInt(el.dataset.counterTarget, 10) || 0;
        var suffix = el.dataset.counterSuffix || '';
        el.textContent = target.toLocaleString() + suffix;
    }

    function animate(el) {
        var target = parseInt(el.dataset.counterTarget, 10) || 0;
        var suffix = el.dataset.counterSuffix || '';
        var duration = 1400;
        var start = performance.now();
        function tick(now) {
            var t = Math.min(1, (now - start) / duration);
            var eased = 1 - Math.pow(1 - t, 3);
            el.textContent = Math.round(target * eased).toLocaleString() + suffix;
            if (t < 1) {
                requestAnimationFrame(tick);
            }
        }
        requestAnimationFrame(tick);
    }

    function init() {
        var counters = document.querySelectorAll('.counter[data-counter-target]');
        if (!counters.length) {
            return;
        }
        if (window.matchMedia('(prefers-reduced-motion: reduce)').matches ||
            typeof IntersectionObserver === 'undefined') {
            counters.forEach(renderFinal);
            return;
        }
        var io = new IntersectionObserver(function (entries) {
            entries.forEach(function (entry) {
                if (entry.isIntersecting) {
                    animate(entry.target);
                    io.unobserve(entry.target);
                }
            });
        }, { threshold: 0.4 });
        counters.forEach(function (el) { io.observe(el); });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();

/**
 * Scrollytelling catalog CSS.
 *
 * The motion rules that drive the className / data-attribute hooks emitted
 * by content pages and headers (.reveal-on-scroll, .hero-content,
 * .scroll-progress, .narrative-pin, hide-on-scroll-down header,
 * active-anchor nav underline). Gated end-to-end on
 * prefers-reduced-motion: no-preference so opted-out users see no motion.
 *
 * Shipped as a separate stylesheet (not folded into style.css) and
 * enqueued frontend-only from scrollytelling.php via wp_enqueue_scripts.
 * The block editor loads style.css inside its iframe canvas for WYSIWYG
 * preview; if the .reveal-on-scroll opacity: 0 rule landed there, every
 * reveal section would render blank in the editor and the canvas would
 * read as uneditable. Living in its own frontend-only file keeps the
 * editor preview unaffected.
**/

@media (prefers-reduced-motion: no-preference) {
    /* Section reveal on enter view */
    .reveal-on-scroll {
        opacity: 0;
        transform: translateY(24px);
        transition: opacity 0.7s ease, transform 0.7s ease;
    }
    .reveal-on-scroll.is-visible {
        opacity: 1;
        transform: translateY(0);
    }

    /* Hero scroll-fade keyed to page scroll so first-screen content starts fully opaque. */
    @supports (animation-timeline: scroll()) {
        .hero-content {
            opacity: 1;
            transform: translateY(0);
            animation: hero-fade linear both;
            animation-timeline: scroll(root);
            animation-range: 0px 60vh;
        }
        @keyframes hero-fade {
            from { opacity: 1; transform: translateY(0); }
            to   { opacity: 0; transform: translateY(-40px); }
        }
    }

    /* Scroll progress bar (CSS scroll-driven animation; older browsers no-op) */
    @supports (animation-timeline: scroll()) {
        .scroll-progress {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            height: 3px;
            background: var(--wp--preset--color--accent, currentColor);
            transform-origin: left center;
            transform: scaleX(0);
            z-index: 1000;
            animation: scroll-progress-grow linear;
            animation-timeline: scroll(root);
            pointer-events: none;
        }
        @keyframes scroll-progress-grow {
            from { transform: scaleX(0); }
            to   { transform: scaleX(1); }
        }
    }

    /* Sticky narrative pin (NYT-style scrolling visuals beside pinned text) */
    .narrative-pin > .wp-block-column:first-child {
        position: sticky;
        top: var(--wp--custom--scroll-padding-top, 96px);
        align-self: flex-start;
    }

    /* Hide-on-scroll-down header variant */
    .wp-site-blocks > header.wp-block-template-part {
        transition: transform 0.3s ease;
    }
    body.header-hidden .wp-site-blocks > header.wp-block-template-part {
        transform: translateY(-100%);
    }

    /* Active-anchor underline (landing-page nav) */
    .wp-block-navigation a {
        position: relative;
    }
    .wp-block-navigation a::after {
        content: '';
        position: absolute;
        left: 0;
        right: 0;
        bottom: -4px;
        height: 2px;
        background: currentColor;
        transform: scaleX(0);
        transform-origin: left center;
        transition: transform 0.3s ease;
    }
    .wp-block-navigation a.is-active::after {
        transform: scaleX(1);
    }
}

/**
 * Toggles `body.is-scrolled` once the viewport has scrolled past a small
 * threshold. The class drives the scrolled-state CSS on the fixed/sticky
 * header (background, blur, shrink, invert, etc.) declared in style.css.
 *
 * Also tracks scroll direction and toggles `body.header-hidden` while the
 * user scrolls DOWN past the threshold, clearing it on any upward gesture.
 * style.css drives the hide-on-scroll-down header variant off that flag.
 * Direction tracking is gated on prefers-reduced-motion so users who
 * opted out of motion never see the header retract/reappear; they get
 * a plain sticky header.
 *
 * Deterministically injected into every theme by AddArbitraryFilesToArtefactTask;
 * functions.php enqueues it only when headerBehavior or a picked scroll
 * variant requires the scrolled state.
 */
(function () {
    'use strict';

    function init() {
        var threshold = 60;
        var scrolled = false;
        var hidden = false;
        var lastY = window.scrollY;
        var directionTracking = !window.matchMedia('(prefers-reduced-motion: reduce)').matches;

        function onScroll() {
            var y = window.scrollY;
            var isScrolled = y > threshold;
            if (isScrolled !== scrolled) {
                scrolled = isScrolled;
                document.body.classList.toggle('is-scrolled', scrolled);
            }
            if (directionTracking) {
                var goingDown = y > lastY && y > 80;
                if (goingDown !== hidden) {
                    hidden = goingDown;
                    document.body.classList.toggle('header-hidden', hidden);
                }
            }
            lastY = y;
        }

        window.addEventListener('scroll', onScroll, { passive: true });
        onScroll();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
